head.b:skin:
/* BrewHouse: all colors and dimensions are intentionally centralized here. */
:root{--espresso-black:#100D0B;--dark-coffee:#211610;--coffee-brown:#38251B;--caramel-gold:#C58B52;--warm-gold:#E6B56E;--cream:#F5EBDD;--warm-white:#FFF9F0;--muted-text:#B9AA9A;--glass-background:rgba(32,22,16,.72);--glass-border:rgba(230,181,110,.22);--container:1400px;--nav-height:84px;--radius:18px;--shadow:0 22px 60px rgba(0,0,0,.35);--duration:.45s}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--espresso-black);color:var(--cream);font:16px/1.6 'DM Sans',sans-serif}body.locked{overflow:hidden}a{color:inherit;text-decoration:none}button,input,select,textarea{font:inherit}button,a{touch-action:manipulation}button{cursor:pointer}img{display:block;max-width:100%}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:2px solid var(--warm-gold);outline-offset:4px}section{scroll-margin-top:var(--nav-height)}.wrap{width:min(var(--container),calc(100% - 10%));margin:auto}.serif,h1,h2,h3{font-family:'Playfair Display',Georgia,serif;font-weight:400;line-height:1.08}h1,h2,h3,p{margin-top:0}.eyebrow{display:flex;align-items:center;gap:10px;color:var(--warm-gold);font-size:.69rem;letter-spacing:.21em;text-transform:uppercase;font-weight:700}.eyebrow:before{content:'';width:27px;height:1px;background:var(--warm-gold)}.muted{color:var(--muted-text)}.small{font-size:.8rem}.button{display:inline-flex;align-items:center;justify-content:center;gap:20px;min-height:48px;padding:12px 25px;border:1px solid transparent;border-radius:50px;background:linear-gradient(120deg,#f2ca8d,#c8894d);color:#1c120d;font-size:.79rem;font-weight:700;transition:transform .25s,filter .25s}.button:hover{transform:translateY(-2px);filter:brightness(1.1)}.button.outline{color:var(--cream);border-color:rgba(245,235,221,.45);background:transparent}.text-link{display:inline-flex;gap:12px;align-items:center;font-size:.8rem;font-weight:600;border-bottom:1px solid var(--caramel-gold);padding-bottom:8px}.site-header{position:fixed;z-index:50;top:0;left:0;right:0;height:var(--nav-height);transition:background .3s,border .3s;border-bottom:1px solid rgba(255,255,255,.08)}.site-header.scrolled,.site-header.open{background:rgba(16,13,11,.95);border-color:var(--glass-border)}.nav{height:100%;display:flex;align-items:center;justify-content:space-between;gap:25px}.brand{display:flex;align-items:center;gap:9px;font-family:Georgia,serif;font-weight:bold;font-size:1.28rem;white-space:nowrap}.brand-mark{font-size:1.9rem;color:var(--warm-gold);line-height:1}.brand sup{font:8px 'DM Sans',sans-serif;align-self:flex-start;margin-left:-7px}.nav-links{display:flex;align-items:center;gap:34px;font-size:.76rem}.nav-links a{color:#e7ded4;transition:color .2s}.nav-links a:hover,.nav-links a.active{color:var(--warm-gold)}.nav-actions{display:flex;gap:12px;align-items:center}.cart-toggle{background:none;border:0;color:var(--cream);padding:10px;white-space:nowrap;font-size:.8rem}.cart-count{color:var(--warm-gold)}.menu-toggle{display:none;background:none;border:1px solid var(--glass-border);color:var(--cream);border-radius:50%;width:44px;height:44px;font-size:1.1rem}.hero{position:relative;min-height:720px;min-height:100svh;display:flex;align-items:center;overflow:hidden;background:#160e0a}.hero-image,.ambience-bg{position:absolute;inset:0;background-size:cover;background-position:center}.hero-image{background-image:linear-gradient(90deg,rgba(10,8,7,.96) 0%,rgba(15,10,8,.77) 40%,rgba(15,10,8,.08) 75%),linear-gradient(0deg,#100d0b 0%,transparent 25%),url('https://images.unsplash.com/photo-1509042239860-f550ce710b93?auto=format&fit=crop&w=2200&q=85');background-position:center}.hero-content{position:relative;z-index:1;padding-top:100px;padding-bottom:100px}.hero-copy{max-width:670px}.hero h1{font-size:clamp(4rem,7.6vw,7.9rem);letter-spacing:-.055em;margin:27px 0 24px;color:#f4d5ae}.hero h1 em{font-weight:400;color:#eac195}.hero p{max-width:390px;color:#d3c7bb;font-size:1rem}.hero-buttons{display:flex;flex-wrap:wrap;gap:12px;margin-top:35px}.hero-bottom{position:absolute;bottom:35px;left:5%;right:5%;display:flex;justify-content:space-between;align-items:end;color:#cfc0ae;font-size:.68rem;letter-spacing:.12em;text-transform:uppercase}.scroll-cue{display:flex;gap:12px;align-items:center}.mouse{width:21px;height:32px;border:1px solid #d6bc9f;border-radius:20px;position:relative}.mouse:after{content:'';position:absolute;left:9px;top:6px;width:2px;height:6px;background:#d6bc9f}.vertical-label{writing-mode:vertical-rl;letter-spacing:.22em}.section{padding:clamp(80px,10vw,150px) 0}.section-heading{font-size:clamp(2.8rem,5vw,5.2rem);letter-spacing:-.04em;margin:20px 0}.section-heading em{color:#dfad78;font-weight:400}.intro-grid{display:grid;grid-template-columns:1fr 1fr;gap:8%;align-items:center}.story-image{position:relative;min-height:570px;border-radius:3px;overflow:hidden}.story-image img,.tile img,.product-image img,.gallery img{width:100%;height:100%;object-fit:cover}.story-image:after{content:'';position:absolute;inset:0;border:1px solid rgba(255,255,255,.12);pointer-events:none}.story-image .image-caption{position:absolute;bottom:25px;left:25px;background:rgba(16,13,11,.75);padding:12px 18px;color:#f3d0a4;font-size:.7rem;letter-spacing:.14em;text-transform:uppercase}.story-copy>p{max-width:500px}.facts{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:35px 0}.fact{border-top:1px solid var(--glass-border);padding-top:18px}.fact span{display:block;color:var(--warm-gold);font-size:1.2rem;margin-bottom:8px}.fact strong{display:block;font-size:.75rem}.fact small{font-size:.68rem;color:var(--muted-text)}.signature{background:radial-gradient(ellipse at 70% 50%,#4a2c1c 0%,#211610 38%,#100d0b 75%);overflow:hidden}.signature-grid{display:grid;grid-template-columns:.85fr 1.15fr;align-items:center;gap:6%}.signature-copy p{max-width:410px}.price{font-family:Georgia,serif;color:#edbf8d;font-size:1.7rem}.signature-art{position:relative;min-height:590px;display:flex;align-items:center;justify-content:center}.signature-art img{width:min(75%,460px);height:540px;object-fit:cover;border-radius:220px 220px 25px 25px;box-shadow:0 25px 90px #0009}.ingredient{position:absolute;font-size:.7rem;line-height:1.5;color:var(--cream);background:rgba(16,13,11,.72);border:1px solid var(--glass-border);padding:9px 12px;border-radius:8px}.ingredient small{display:block;color:var(--muted-text)}.ingredient.one{top:18%;right:0}.ingredient.two{top:43%;left:0}.ingredient.three{bottom:17%;right:0}.menu-section{background:#16100d}.section-top{display:flex;justify-content:space-between;align-items:end;gap:20px;margin-bottom:35px}.section-top .section-heading{margin-bottom:0}.filters{display:flex;flex-wrap:wrap;gap:8px;margin:28px 0}.filter{border:1px solid var(--glass-border);background:transparent;color:var(--muted-text);padding:9px 17px;border-radius:30px;font-size:.75rem}.filter.active,.filter:hover{background:var(--warm-gold);border-color:var(--warm-gold);color:#211610}.menu-layout{display:grid;grid-template-columns:1.2fr .8fr;gap:22px}.showcase{position:relative;min-width:0;background:linear-gradient(135deg,#302017,#19110d);border:1px solid var(--glass-border);border-radius:var(--radius);overflow:hidden;display:grid;grid-template-columns:1fr 1fr;min-height:450px}.product-image{min-height:350px;overflow:hidden}.product-image img{transition:opacity .25s}.product-info{padding:45px 35px;display:flex;flex-direction:column;justify-content:center}.product-info h3{font-size:clamp(2rem,3vw,3.3rem);margin:12px 0}.product-info p{font-size:.83rem;color:var(--muted-text)}.tag{color:var(--warm-gold);font-size:.65rem;letter-spacing:.16em;text-transform:uppercase}.carousel-controls{display:flex;align-items:center;gap:10px;margin-top:25px}.round{width:42px;height:42px;border:1px solid var(--glass-border);border-radius:50%;background:transparent;color:var(--cream);font-size:1.1rem}.round:hover{border-color:var(--warm-gold)}.customizer{padding:30px;background:#211711;border:1px solid var(--glass-border);border-radius:var(--radius)}.customizer h3{font-size:1.65rem;margin:8px 0}.customizer p{font-size:.75rem}.field-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.field{display:flex;flex-direction:column;gap:6px;min-width:0}.field label{color:#d8c9b8;font-size:.73rem}.field input,.field select,.field textarea{width:100%;min-height:45px;border:1px solid #674b37;border-radius:7px;color:var(--cream);background:#160f0c;padding:10px 12px}.field textarea{resize:vertical;min-height:90px}.custom-actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-top:20px}.custom-actions .button{flex:1}.reset{border:0;background:none;color:var(--muted-text);text-decoration:underline;font-size:.75rem}.notice{color:var(--muted-text);font-size:.72rem}.bakery-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.tile{min-height:430px;position:relative;overflow:hidden;border-radius:var(--radius)}.tile img{position:absolute;inset:0;transition:transform .7s}.tile:hover img{transform:scale(1.04)}.tile:after{content:'';position:absolute;inset:0;background:linear-gradient(0deg,rgba(10,7,5,.9),transparent 80%)}.tile-content{position:absolute;z-index:1;bottom:30px;left:30px;right:30px}.tile-content h3{font-size:2rem;margin:8px 0}.ambience{position:relative;min-height:650px;display:flex;align-items:center;overflow:hidden}.ambience-bg{background-image:linear-gradient(90deg,rgba(12,8,6,.95),rgba(12,8,6,.62) 45%,rgba(12,8,6,.15)),url('https://images.unsplash.com/photo-1445116572660-236099ec97a0?auto=format&fit=crop&w=2000&q=80')}.ambience .wrap{position:relative}.ambience-copy{max-width:610px}.ambience-copy p{max-width:420px}.reviews{background:#1b130f}.review-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.review{border:1px solid var(--glass-border);padding:30px;border-radius:12px;background:#211812}.stars{color:var(--warm-gold);letter-spacing:.2em}.review blockquote{margin:20px 0;font-family:Georgia,serif;font-size:1.15rem;line-height:1.5}.reservation{background:radial-gradient(circle at 20% 40%,#49301d,#17100c 60%)}.reserve-grid{display:grid;grid-template-columns:1fr 1fr;gap:10%;align-items:start}.form-card{background:rgba(16,13,11,.8);border:1px solid var(--glass-border);padding:clamp(22px,4vw,40px);border-radius:var(--radius)}.form-card h3{font-size:2rem}.form-card .field-grid{margin-bottom:15px}.form-card .field{margin-bottom:14px}.form-card .button{width:100%}.form-message{min-height:1.5em;margin:12px 0 0;color:#efd1a7;font-size:.8rem}.footer{padding:70px 0 25px;background:#0c0908;border-top:1px solid var(--glass-border)}.footer-grid{display:grid;grid-template-columns:2fr 1fr 1fr 1.3fr;gap:35px}.footer h4{color:var(--warm-gold);font-size:.7rem;text-transform:uppercase;letter-spacing:.15em}.footer p,.footer a{font-size:.78rem;color:var(--muted-text)}.footer-links{display:grid;gap:8px}.footer-bottom{margin-top:60px;padding-top:22px;border-top:1px solid var(--glass-border);display:flex;justify-content:space-between;gap:15px;font-size:.7rem;color:var(--muted-text)}.subpage{padding-top:var(--nav-height);min-height:70vh}.sub-hero{padding:100px 0 70px;background:radial-gradient(circle at 75% 30%,#4b3020,#140e0b 60%)}.sub-hero h1{font-size:clamp(3.5rem,7vw,7rem);letter-spacing:-.05em;margin:20px 0}.sub-hero p{max-width:580px;color:var(--muted-text)}.gallery{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.gallery figure{margin:0}.gallery img{height:300px;border-radius:10px}.gallery figcaption{color:var(--muted-text);font-size:.75rem;padding-top:8px}.catalog{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.catalog-card{border:1px solid var(--glass-border);background:#211711;border-radius:12px;overflow:hidden}.catalog-card img{width:100%;height:220px;object-fit:cover}.catalog-card div{padding:20px}.catalog-card h3{font-size:1.5rem;margin:8px 0}.catalog-card p{font-size:.8rem;color:var(--muted-text);min-height:3em}.catalog-card button{margin-top:10px}.contact-grid{display:grid;grid-template-columns:1fr 1fr;gap:8%}.contact-list{display:grid;gap:22px}.contact-list strong{display:block;color:var(--warm-gold);font-size:.7rem;text-transform:uppercase;letter-spacing:.14em}.drawer-backdrop{position:fixed;z-index:70;inset:0;background:#000a}.drawer{position:fixed;z-index:71;right:0;top:0;bottom:0;width:min(440px,100%);background:#1c130e;border-left:1px solid var(--glass-border);padding:30px;overflow:auto;box-shadow:var(--shadow)}.drawer-head{display:flex;justify-content:space-between;align-items:center}.drawer h2{font-size:2rem}.cart-item{border-bottom:1px solid var(--glass-border);padding:20px 0}.cart-item strong{display:block}.cart-item small{color:var(--muted-text)}.cart-row{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:10px}.cart-row input{width:65px;background:#100d0b;color:var(--cream);border:1px solid var(--glass-border);padding:7px}.cart-row button{background:none;border:0;color:#e5b787;text-decoration:underline}.cart-total{display:flex;justify-content:space-between;padding:25px 0}.hidden,[hidden]{display:none!important}.blog-area{padding:120px 5% 60px;max-width:1100px;margin:auto}.blog-area a{color:var(--warm-gold)}.blog-area img{max-width:100%;height:auto}.skip{position:fixed;top:-100px;left:10px;z-index:100;background:var(--warm-gold);color:#100d0b;padding:10px}.skip:focus{top:10px}
@media(max-width:900px){:root{--nav-height:72px}.nav-links{display:none;position:absolute;top:72px;left:0;right:0;background:#160f0c;padding:20px 5% 28px;flex-direction:column;align-items:stretch;gap:0;border-bottom:1px solid var(--glass-border)}.site-header.open .nav-links{display:flex}.nav-links a{padding:12px 0;font-size:.95rem}.menu-toggle{display:block}.nav-order{display:none}.intro-grid,.signature-grid,.reserve-grid,.contact-grid{grid-template-columns:1fr;gap:45px}.story-image{min-height:440px;order:2}.menu-layout{grid-template-columns:1fr}.footer-grid{grid-template-columns:1fr 1fr}.signature-art{min-height:490px}.signature-art img{height:460px}.hero-image{background-position:60% center}.gallery,.catalog{grid-template-columns:repeat(2,1fr)}}
@media(max-width:600px){.wrap{width:calc(100% - 36px)}.hero{min-height:700px;min-height:100svh;align-items:flex-end}.hero-image{background-image:linear-gradient(0deg,#100d0b 0%,rgba(16,13,11,.75) 35%,rgba(16,13,11,.18) 100%),url('https://images.unsplash.com/photo-1509042239860-f550ce710b93?auto=format&fit=crop&w=1000&q=80');background-position:60% center}.hero-content{padding:150px 0 125px}.hero h1{font-size:clamp(3.4rem,13vw,5.5rem)}.hero-bottom{left:18px;right:18px}.vertical-label{display:none}.section{padding:80px 0}.section-heading{font-size:clamp(2.7rem,11vw,4rem)}.facts{gap:8px}.story-image{min-height:370px}.signature-art{min-height:420px}.signature-art img{height:390px;width:72%}.ingredient{font-size:.62rem;padding:7px}.ingredient.one,.ingredient.three{right:0}.ingredient.two{left:0}.section-top{align-items:start;flex-direction:column}.showcase{grid-template-columns:1fr}.product-image{height:280px;min-height:0}.product-info{padding:25px}.bakery-grid,.review-grid,.gallery,.catalog{grid-template-columns:1fr}.tile{min-height:350px}.ambience{min-height:600px}.footer-grid{grid-template-columns:1fr 1fr}.footer-grid>div:first-child{grid-column:1/-1}.footer-bottom{flex-direction:column}.sub-hero{padding:75px 0 50px}.field-grid{gap:10px}.brand{font-size:1.1rem}.cart-toggle{padding:6px;font-size:.72rem}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*:before,*:after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}}

body.script:
/* CONFIGURATION: Replace illustrative data before publishing. No secrets belong here.
   Images are external illustrative Unsplash images; replace with licensed cafe assets.
   Set reservationEmail to enable an email request, and contact/social URLs only when known.
   Prices are demo prices and must be verified server-side for real ordering. */
const CONFIG = {
  brand: 'BrewHouse', logo: '', currency: '₹', address: '', phone: '', email: '', hours: '',
  mapsUrl: '', instagram: '', facebook: '', reservationEmail: '', whatsapp: '',
  products: [
    {id:'latte',name:'Classic Latte',category:'Coffee',description:'Smooth espresso with silky steamed milk.',price:290,image:'https://images.unsplash.com/photo-1541167760496-1628856ab772?auto=format&fit=crop&w=900&q=80',available:true,customizable:true,temperatures:['Hot','Iced']},
    {id:'cappuccino',name:'Cappuccino',category:'Coffee',description:'A balanced espresso topped with velvety foam.',price:280,image:'https://images.unsplash.com/photo-1534778101976-62847782c213?auto=format&fit=crop&w=900&q=80',available:true,customizable:true,temperatures:['Hot']},
    {id:'coldbrew',name:'Cold Brew',category:'Cold drinks',description:'A refreshing, slow-inspired coffee served over ice.',price:250,image:'https://images.unsplash.com/photo-1517701604599-bb29b565090c?auto=format&fit=crop&w=900&q=80',available:true,customizable:true,temperatures:['Iced']},
    {id:'frappe',name:'Caramel Frappe',category:'Cold drinks',description:'A creamy chilled coffee with a caramel finish.',price:320,image:'https://images.unsplash.com/photo-1572490122747-3968b75cc699?auto=format&fit=crop&w=900&q=80',available:true,customizable:true,temperatures:['Iced']},
    {id:'matcha',name:'Matcha Latte',category:'Tea & specialty',description:'Earthy matcha and creamy milk in perfect harmony.',price:320,image:'https://images.unsplash.com/photo-1515823064-d6e0c04616a7?auto=format&fit=crop&w=900&q=80',available:true,customizable:true,temperatures:['Hot','Iced']},
    {id:'croissant',name:'Butter Croissant',category:'Bakery',description:'A golden, flaky companion to your favorite coffee.',price:180,image:'https://images.unsplash.com/photo-1555507036-ab1f4038808a?auto=format&fit=crop&w=900&q=80',available:true,customizable:false,temperatures:[]},
    {id:'cake',name:'Chocolate Cake',category:'Desserts',description:'A rich chocolate treat for a little extra indulgence.',price:260,image:'https://images.unsplash.com/photo-1578985545062-69928b1d9587?auto=format&fit=crop&w=900&q=80',available:true,customizable:false,temperatures:[]}
  ], sizePrices:{Regular:0,Large:40}, milkPrices:{Regular:0,Oat:30,Almond:30}
};
(function(){
'use strict';
const $ = id => document.getElementById(id); const all = s => Array.from(document.querySelectorAll(s));
const money = n => CONFIG.currency + Number(n).toFixed(0); const validQty = n => Number.isInteger(n) && n >= 1 && n <= 20;
const safeUrl = value => { try { const u = new URL(value); return u.protocol === 'https:' ? u.href : ''; } catch (_) { return ''; } };
const escapeHtml = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
all('.brand-name').forEach(el => el.textContent = CONFIG.brand); all('[data-config]').forEach(el => { el.textContent = CONFIG[el.dataset.config] || 'Not configured'; }); $('year').textContent = new Date().getFullYear();
if(CONFIG.logo && safeUrl(CONFIG.logo)){all('.brand-mark').forEach(el => { const img=document.createElement('img'); img.src=safeUrl(CONFIG.logo); img.alt=''; img.style.maxHeight='40px'; el.replaceChildren(img); });}
const header=$('header'), toggle=$('menu-toggle'); function closeNav(){header.classList.remove('open');toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Open navigation');}
toggle.addEventListener('click',()=>{const open=header.classList.toggle('open');toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Close navigation':'Open navigation');});
window.addEventListener('scroll',()=>header.classList.toggle('scrolled',window.scrollY>30),{passive:true});
const pages=all('[data-page]'); function route(){if(!pages.length)return; let name=location.hash.slice(1) || 'home'; if(!pages.some(p=>p.dataset.page===name)) name='home'; pages.forEach(p=>p.classList.toggle('hidden',p.dataset.page!==name)); all('.nav-links a').forEach(a=>a.classList.toggle('active',a.hash==='#'+name)); closeNav(); window.scrollTo(0,0);}
window.addEventListener('hashchange',route); all('.nav-links a').forEach(a=>a.addEventListener('click',closeNav)); route();
let cart=[]; try {let saved=JSON.parse(localStorage.getItem('brewhouse-cart')||'[]');if(Array.isArray(saved)) cart=saved.filter(x=>x && CONFIG.products.some(p=>p.id===x.id) && validQty(x.qty) && x.options && typeof x.options==='object');}catch(_){}
function unitPrice(product,options){return product.price+(product.customizable ? (CONFIG.sizePrices[options.size]||0)+(CONFIG.milkPrices[options.milk]||0) : 0);}
function save(){try{localStorage.setItem('brewhouse-cart',JSON.stringify(cart));}catch(_){} renderCart();}
function optionsText(item){return item.options.size ? [item.options.temperature,item.options.size,item.options.milk+' milk',item.options.sugar+' sugar'].join(' · ') : 'Standard';}
function renderCart(){let total=0; $('cart-count').textContent=cart.reduce((sum,x)=>sum+x.qty,0); $('cart-items').innerHTML=cart.length?'':'<p class="muted">Your bag is empty. Find something lovely on our menu.</p>'; cart.forEach((item,i)=>{const p=CONFIG.products.find(p=>p.id===item.id);if(!p)return; const price=unitPrice(p,item.options);total+=price*item.qty;const el=document.createElement('div');el.className='cart-item';el.innerHTML='<strong>'+escapeHtml(p.name)+'</strong><small>'+escapeHtml(optionsText(item))+'</small><div class="cart-row"><span>'+money(price)+' each</span><label>Qty <input aria-label="Quantity for '+escapeHtml(p.name)+'" type="number" min="1" max="20" value="'+item.qty+'"/></label><button type="button">Remove</button></div>';el.querySelector('input').addEventListener('change',e=>{const n=Number(e.target.value);if(validQty(n)){item.qty=n;save();}else{e.target.value=item.qty;}});el.querySelector('button').addEventListener('click',()=>{cart.splice(i,1);save();});$('cart-items').appendChild(el);});$('cart-total').textContent=money(total);}
let lastFocus; function openCart(){lastFocus=document.activeElement;$('cart-drawer').classList.remove('hidden');$('drawer-backdrop').classList.remove('hidden');document.body.classList.add('locked');$('cart-close').focus();} function closeCart(){$('cart-drawer').classList.add('hidden');$('drawer-backdrop').classList.add('hidden');document.body.classList.remove('locked');if(lastFocus)lastFocus.focus();}
$('cart-open').addEventListener('click',openCart);$('cart-close').addEventListener('click',closeCart);$('drawer-backdrop').addEventListener('click',closeCart);document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeNav();if(!$('cart-drawer').classList.contains('hidden'))closeCart();} if(e.key==='Tab'&&!$('cart-drawer').classList.contains('hidden')){const focusable=Array.from($('cart-drawer').querySelectorAll('button,input,a[href]')).filter(x=>!x.disabled);const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
$('checkout').addEventListener('click',()=>{$('checkout-message').textContent=cart.length?'Demo only: no order or payment has been submitted.':'Your bag is empty.';});renderCart();
if(!pages.length)return;
let category='All',catalogCategory='All',index=0;const categories=['All',...new Set(CONFIG.products.map(p=>p.category))];const featured=()=>CONFIG.products.filter(p=>category==='All'||p.category===category);let selected=featured()[0];
function filters(id,current,callback){const container=$(id);container.innerHTML='';categories.forEach(cat=>{let b=document.createElement('button');b.type='button';b.className='filter'+(cat===current?' active':'');b.textContent=cat;b.setAttribute('aria-pressed',String(cat===current));b.addEventListener('click',()=>callback(cat));container.appendChild(b);});}
function resetOptions(){ $('size').value='Regular';$('milk').value='Regular';$('sugar').value='50%';$('quantity').value=1;updateFeatured(); }
function updateFeatured(){const list=featured();if(!list.length)return;index=(index+list.length)%list.length;selected=list[index];$('featured-image').src=selected.image;$('featured-image').alt='Illustrative '+selected.name;$('featured-category').textContent=selected.category+' · Demo';$('featured-name').textContent=selected.name;$('featured-description').textContent=selected.description;$('featured-price').textContent=money(selected.price);$('featured-availability').textContent=selected.available?'Demo availability: available':'Currently unavailable';$('product-position').textContent=(index+1)+' / '+list.length;const temp=$('temperature'); Array.from(temp.options).forEach(o=>{o.disabled=!selected.temperatures.includes(o.value);});if(selected.customizable&&!selected.temperatures.includes(temp.value))temp.value=selected.temperatures[0];['temperature','size','milk','sugar'].forEach(id=>$(id).disabled=!selected.customizable);$('add-cart').disabled=!selected.available;updatePrice();}
function getOptions(){return selected.customizable?{temperature:$('temperature').value,size:$('size').value,milk:$('milk').value,sugar:$('sugar').value}:{};}
function updatePrice(){let qty=Number($('quantity').value);$('custom-price').textContent=validQty(qty)?'· '+money(unitPrice(selected,getOptions())*qty):'';$('custom-message').textContent=selected.customizable?'':'This item is served as shown; drink options do not apply.';}
// Rebuild filter callbacks explicitly (no reliance on inline handlers).
function homeFilters(){filters('home-filters',category,cat=>{category=cat;index=0;homeFilters();resetOptions();});}homeFilters();
$('previous-product').addEventListener('click',()=>{index--;resetOptions();});$('next-product').addEventListener('click',()=>{index++;resetOptions();});['temperature','size','milk','sugar','quantity'].forEach(id=>$(id).addEventListener('input',updatePrice));$('reset-custom').addEventListener('click',resetOptions);
$('add-cart').addEventListener('click',()=>{let qty=Number($('quantity').value),options=getOptions();if(!validQty(qty)){ $('custom-message').textContent='Please choose a quantity between 1 and 20.';return;}if(!selected.available || (selected.customizable&&!selected.temperatures.includes(options.temperature))){$('custom-message').textContent='This combination is unavailable.';return;}let existing=cart.find(x=>x.id===selected.id&&JSON.stringify(x.options)===JSON.stringify(options));if(existing){if(existing.qty+qty>20){$('custom-message').textContent='A bag item can contain at most 20. Adjust the quantity in your bag.';return;}existing.qty+=qty;}else cart.push({id:selected.id,options,qty});save();$('custom-message').textContent=selected.name+' added to your demo bag.';});
function catalogFilters(){filters('catalog-filters',catalogCategory,cat=>{catalogCategory=cat;catalogFilters();renderCatalog();});}function renderCatalog(){const term=$('menu-search').value.trim().toLowerCase();const list=CONFIG.products.filter(p=>(catalogCategory==='All'||p.category===catalogCategory)&&(p.name+' '+p.description+' '+p.category).toLowerCase().includes(term));$('catalog').innerHTML='';list.forEach(p=>{const card=document.createElement('article');card.className='catalog-card';card.innerHTML='<img loading="lazy" src="'+escapeHtml(p.image)+'" alt="Illustrative '+escapeHtml(p.name)+'"/><div><span class="tag">'+escapeHtml(p.category)+' · '+(p.available?'Demo available':'Unavailable')+'</span><h3>'+escapeHtml(p.name)+'</h3><p>'+escapeHtml(p.description)+'</p><strong>'+money(p.price)+'</strong><br/><button class="button" type="button">'+(p.customizable?'Customize':'Select item')+' →</button></div>';card.querySelector('button').addEventListener('click',()=>{category='All';index=CONFIG.products.findIndex(x=>x.id===p.id);homeFilters();resetOptions();location.hash='home';setTimeout(()=>{$('home-menu').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});},0);});$('catalog').appendChild(card);});$('catalog-status').textContent=list.length?list.length+' demo item'+(list.length===1?'':'s'):'No items match your search.';}
$('menu-search').addEventListener('input',renderCatalog);catalogFilters();renderCatalog();updateFeatured();const frappe=CONFIG.products.find(p=>p.id==='frappe');if(frappe)$('signature-price').textContent=money(frappe.price);
const date=$('res-date'); const now=new Date();date.min=now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0')+'-'+String(now.getDate()).padStart(2,'0');
$('reservation-form').addEventListener('submit',e=>{e.preventDefault();const phone=$('res-phone').value.trim(),d=date.value,msg=$('reservation-message');if(!/^[+\d\s()-]{7,20}$/.test(phone)||phone.replace(/\D/g,'').length<7){msg.textContent='Please enter a valid phone number with at least 7 digits.';$('res-phone').focus();return;}if(d<date.min){msg.textContent='Please choose today or a future date.';date.focus();return;}if(!CONFIG.reservationEmail){msg.textContent='Demo only: no reservation request was sent. Booking is not configured.';return;}const subject=encodeURIComponent('Table request for '+d);const body=encodeURIComponent('Name: '+$('res-name').value+'\nPhone: '+phone+'\nDate: '+d+'\nTime: '+$('res-time').value+'\nGuests: '+$('res-guests').value+'\nNotes: '+$('res-notes').value);msg.textContent='Your email app will open. This is a request, not a confirmed reservation.';location.href='mailto:'+encodeURIComponent(CONFIG.reservationEmail)+'?subject='+subject+'&body='+body;});
$('contact-form').addEventListener('submit',e=>{e.preventDefault();if(!CONFIG.email){$('contact-status').textContent='Demo only: no message was sent. Contact email is not configured.';return;}$('contact-status').textContent='Your email app will open; please send the message there.';location.href='mailto:'+encodeURIComponent(CONFIG.email)+'?subject='+encodeURIComponent('Message from '+$('contact-name').value)+'&body='+encodeURIComponent('Reply to: '+$('contact-email').value+'\n\n'+$('contact-message').value);});
[['mapsUrl','Get directions'],['instagram','Instagram'],['facebook','Facebook']].forEach(([key,label])=>{const url=safeUrl(CONFIG[key]);if(url){const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener noreferrer';a.className='text-link';a.style.marginRight='16px';a.textContent=label+' ↗';$('contact-links').appendChild(a);}});
})();
